// Allow importing CSS/SASS files in TypeScript files (side-effect imports and CSS modules)
declare module "*.css";
declare module "*.scss";
declare module "*.sass";

declare module "*.module.css";
declare module "*.module.scss";
declare module "*.module.sass";

// Static assets
declare module "*.png";
declare module "*.jpg";
declare module "*.jpeg";
declare module "*.svg";
declare module "*.webp";
declare module "*.gif";
